{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Amoxicillin, which shares the query's p-hydroxyphenylglycine alpha-amino side chain, has an absolute oral bioavailability of 93% at 500 mg in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Cephradine, a close cephem analogue with an alpha-amino side chain, is >90% absolutely bioavailable in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Loracarbef, a carbacephem with a phenylglycine alpha-amino side chain, is approximately 90% bioavailable after oral administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A cefoperazone-like cephalosporin with both p-hydroxyphenylglycine and a 3-thioheterocycle shows about 40% oral bioavailability in humans, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Cefazolin, which shares the 3-thioheterocycle but lacks the alpha-amino phenylglycine side chain, has only 1.5-2% oral bioavailability; this low-F evidence is less transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ceftriaxone, another 3-thioheterocycle cephalosporin without the alpha-amino phenylglycine side chain, has 8% oral bioavailability, but its side-chain difference limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the query combines an alpha-amino p-hydroxyphenylglycine side chain—the key determinant of oral absorption in amoxicillin, cephradine, and loracarbef—with a cephem scaffold. The 3-thioheterocycle is shared with some low-F parenteral cephalosporins, but those lack the critical amino-acid side chain, and the closest cefoperazone-like analogue is reported at about 40% oral bioavailability.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the query molecule.",
    "No quantitative intestinal transporter (e.g., PEPT1) data for the 3-thioheterocycle substituent.",
    "The cefoperazone-like record C14 is the only direct combination of p-hydroxyphenylglycine and a 3-thioheterocycle, and its identity/conditions are not fully specified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

